#include <stdio.h>

int main()
{
    int n, a[100], sum = 0;
    scanf("%d", &n);
    for (int i = 0; i < n; i++)
    {
        scanf("%d", &a[i]);
        sum += a[i];
    }
    double avg = (double)sum / n;
    printf("%.2f\n", avg);
    int first = 1;
    for (int i = 0; i < n; i++)
    {
        if (a[i] > avg)
        {
            if (!first)
            {
                printf(" ");
            }
            printf("%d", a[i]);
            first = 0;
        }
    }
    printf("\n");
    return 0;
}

