#include <stdio.h>

int main()
{
    int r, c;
    char m[20][21];
    scanf("%d %d", &r, &c);
    for (int i = 0; i < r; i++)
    {
        scanf("%s", m[i]);
    }
    for (int i = 0; i < r; i++)
    {
        for (int j = 0; j < c; j++)
        {
            if (m[i][j] == '*')
            {
                printf("*");
                continue;
            }
            int cnt = 0;
            for (int di = -1; di <= 1; di++)
            {
                for (int dj = -1; dj <= 1; dj++)
                {
                    int y = i + di, x = j + dj;
                    if (y >= 0 && y < r && x >= 0 && x < c && m[y][x] == '*')
                    {
                        cnt++;
                    }
                }
            }
            printf("%d", cnt);
        }
        printf("\n");
    }
    return 0;
}

