#include <stdio.h>

int max2(int a, int b)
{
    return a > b ? a : b;
}

int min2(int a, int b)
{
    return a < b ? a : b;
}

int main()
{
    int ax1, ay1, ax2, ay2, bx1, by1, bx2, by2;
    scanf("%d %d %d %d", &ax1, &ay1, &ax2, &ay2);
    scanf("%d %d %d %d", &bx1, &by1, &bx2, &by2);
    long long total = (long long)(ax2 - ax1) * (ay2 - ay1) + (long long)(bx2 - bx1) * (by2 - by1);
    int w = min2(ax2, bx2) - max2(ax1, bx1);
    int h = min2(ay2, by2) - max2(ay1, by1);
    if (w > 0 && h > 0)
    {
        total -= (long long)w * h;
    }
    printf("%lld\n", total);
    return 0;
}

