#include <stdio.h>

int n, t[8], pre[8], used[8];
int best = 1000000000;

void go(int count, int now, int sum)
{
    if (count == n)
    {
        if (sum < best)
        {
            best = sum;
        }
        return;
    }
    for (int i = 1; i <= n; i++)
    {
        if (used[i] || (pre[i] != 0 && !used[pre[i]]))
        {
            continue;
        }
        used[i] = 1;
        go(count + 1, now + t[i], sum + now + t[i]);
        used[i] = 0;
    }
}

int main()
{
    scanf("%d", &n);
    for (int i = 1; i <= n; i++)
    {
        scanf("%d %d", &t[i], &pre[i]);
    }
    go(0, 0, 0);
    printf("%d\n", best);
    return 0;
}

