int n;
int len[1000];

long long cut(int h)
{
    long long total = 0;
    for (int i = 0; i < n; i++)
    {
        if (len[i] > h)
        {
            total += len[i] - h;
        }
    }
    return total;
}

int main()
{
    long long m;
    int lo = 0, hi = 0;
    scanf("%d %lld", &n, &m);
    for (int i = 0; i < n; i++)
    {
        scanf("%d", &len[i]);
        if (len[i] > hi)
        {
            hi = len[i];
        }
    }
    while (lo < hi)
    {
        int mid = (lo + hi + 1) / 2;
        if (cut(mid) >= m)
        {
            lo = mid;
        }
        else
        {
            hi = mid - 1;
        }
    }
    printf("%d\n", lo);
    return 0;
}

