int first[10001], next[10001], depth[10001], queue[10001], count[10002];

int main()
{
    int n;
    scanf("%d", &n);
    for (int i = 0; i <= n; i++)
    {
        first[i] = 0;
    }
    for (int v = 2; v <= n; v++)
    {
        int p;
        scanf("%d", &p);
        next[v] = first[p];
        first[p] = v;
    }
    int head = 0, tail = 0, levels = 0;
    queue[tail++] = 1;
    depth[1] = 1;
    while (head < tail)
    {
        int u = queue[head++];
        count[depth[u]]++;
        if (depth[u] > levels)
        {
            levels = depth[u];
        }
        for (int c = first[u]; c != 0; c = next[c])
        {
            depth[c] = depth[u] + 1;
            queue[tail++] = c;
        }
    }
    printf("%d\n", levels);
    for (int d = 1; d <= levels; d++)
    {
        printf("%d%c", count[d], d == levels ? '\n' : ' ');
    }
    return 0;
}

