int head[1001], nxt[5000], to[5000], indeg[1001], done[1001], order[1000];

int main()
{
    int n, m;
    scanf("%d %d", &n, &m);
    for (int i = 0; i < m; i++)
    {
        int a, b;
        scanf("%d %d", &a, &b);
        to[i] = b;
        nxt[i] = head[a];
        head[a] = i + 1;
        indeg[b]++;
    }
    for (int step = 0; step < n; step++)
    {
        int pick = 0;
        for (int v = 1; v <= n; v++)
        {
            if (!done[v] && indeg[v] == 0)
            {
                pick = v;
                break;
            }
