        if (pick == 0)
        {
            printf("-1\n");
            return 0;
        }
        done[pick] = 1;
        order[step] = pick;
        for (int e = head[pick]; e != 0; e = nxt[e - 1])
        {
            indeg[to[e - 1]]--;
        }
    }
    for (int i = 0; i < n; i++)
    {
        printf("%d%c", order[i], i == n - 1 ? '\n' : ' ');
    }
    return 0;
}

