#include <stdio.h>
#include <stdlib.h>

typedef struct
{
    int a;
    int b;
    int c;
} Edge;

Edge e[10000];
int parent[2001];

int compare(const void *p, const void *q)
{
    const Edge *x = p;
    const Edge *y = q;
    return (x->c > y->c) - (x->c < y->c);
}

int find(int x)
{
    while (parent[x] != x)
    {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

int main()
{
    int n, m, used = 0;
    long long cost = 0;
    scanf("%d %d", &n, &m);
    for (int i = 0; i < m; i++)
    {
        scanf("%d %d %d", &e[i].a, &e[i].b, &e[i].c);
    }
    for (int i = 1; i <= n; i++)
    {
        parent[i] = i;
    }
    qsort(e, m, sizeof(Edge), compare);
    for (int i = 0; i < m && used < n - 1; i++)
    {
        int ra = find(e[i].a), rb = find(e[i].b);
        if (ra != rb)
        {
            parent[ra] = rb;
            cost += e[i].c;
            used++;
        }
    }
    if (used == n - 1)
    {
        printf("%lld\n", cost);
    }
    else
    {
        printf("-1\n");
    }
    return 0;
}

