#include <stdio.h>

int n;
long long bit[100001];

void add(int i, long long x)
{
    for (; i <= n; i += i & -i)
    {
        bit[i] += x;
    }
}

long long prefix(int i)
{
    long long s = 0;
    for (; i > 0; i -= i & -i)
    {
        s += bit[i];
    }
    return s;
}

int main()
{
    int q;
    scanf("%d %d", &n, &q);
    for (int k = 0; k < q; k++)
    {
        int type, a, b;
        scanf("%d %d %d", &type, &a, &b);
        if (type == 1)
        {
            add(a, b);
        }
        else
        {
            printf("%lld\n", prefix(b) - prefix(a - 1));
        }
    }
    return 0;
}

