{
    int h, w;
    scanf("%d %d", &h, &w);
    for (int y = 0; y < h; y++)
    {
        scanf("%s", grid[y]);
    }
    for (int y = 0; y < h; y++)
    {
        for (int x = 0; x < w; x++)
        {
            if (grid[y][x] == '#')
            {
                ways[y][x] = 0;
            }
            else if (y == 0 && x == 0)
            {
                ways[y][x] = 1;
            }
            else
            {
                int up = y > 0 ? ways[y - 1][x] : 0;
                int left = x > 0 ? ways[y][x - 1] : 0;
                ways[y][x] = (up + left) % MOD;
            }
        }
    }
    printf("%d\n", ways[h - 1][w - 1]);
    return 0;
}

