#include <stdio.h>

#define INF 2000000000

int n;
int tree[20000];

void update(int node, int s, int e, int i, int x)
{
    if (s == e)
    {
        tree[node] = x;
        return;
    }
    int mid = (s + e) / 2;
    if (i <= mid)
    {
        update(node * 2, s, mid, i, x);
    }
    else
    {
        update(node * 2 + 1, mid + 1, e, i, x);
    }
    int a = tree[node * 2], b = tree[node * 2 + 1];
    tree[node] = a < b ? a : b;
}

int query(int node, int s, int e, int l, int r)
{
    if (r < s || e < l)
    {
        return INF;
    }
    if (l <= s && e <= r)
    {
        return tree[node];
    }
    int mid = (s + e) / 2;
    int a = query(node * 2, s, mid, l, r);
    int b = query(node * 2 + 1, mid + 1, e, l, r);
    return a < b ? a : b;
}

int main()
{
    int q;
    scanf("%d %d", &n, &q);
    for (int i = 1; i <= n; i++)
    {
        int x;
        scanf("%d", &x);
        update(1, 1, n, i, x);
    }
    for (int k = 0; k < q; k++)
    {
        int type, a, b;
        scanf("%d %d %d", &type, &a, &b);
        if (type == 1)
        {
            update(1, 1, n, a, b);
        }
        else
        {
            printf("%d\n", query(1, 1, n, a, b));
        }
    }
    return 0;
}

