#include <stdio.h>

#define INF 1000000000

int t[10][10];
int dp[1 << 10][10];

int main()
{
    int n;
    scanf("%d", &n);
    for (int i = 0; i < n; i++)
    {
        for (int j = 0; j < n; j++)
        {
            scanf("%d", &t[i][j]);
        }
    }
    int full = (1 << n) - 1;
    for (int mask = 0; mask <= full; mask++)
    {
        for (int i = 0; i < n; i++)
        {
            dp[mask][i] = INF;
        }
    }
    dp[1][0] = 0;
    for (int mask = 1; mask <= full; mask++)
    {
        for (int i = 0; i < n; i++)
        {
            if (dp[mask][i] == INF)
            {
                continue;
            }
            for (int j = 0; j < n; j++)
            {
                if (mask & (1 << j))
                {
                    continue;
                }
                int next = mask | (1 << j);
                int value = dp[mask][i] + t[i][j];
                if (value < dp[next][j])
                {
                    dp[next][j] = value;
                }
            }
        }
    }
    int best = INF;
    for (int i = 1; i < n; i++)
    {
        if (dp[full][i] + t[i][0] < best)
        {
            best = dp[full][i] + t[i][0];
        }
    }
    printf("%d\n", best);
    return 0;
}

