#include <stdio.h>

long long tree[200000], lazy[200000];
int value[50001];

void build(int node, int s, int e)
{
    if (s == e)
    {
        tree[node] = value[s];
        return;
    }
    int mid = (s + e) / 2;
    build(node * 2, s, mid);
    build(node * 2 + 1, mid + 1, e);
    tree[node] = tree[node * 2] + tree[node * 2 + 1];
}

void push(int node, int s, int e)
{
    if (lazy[node] != 0)
    {
        int mid = (s + e) / 2;
        tree[node * 2] += lazy[node] * (mid - s + 1);
        tree[node * 2 + 1] += lazy[node] * (e - mid);
        lazy[node * 2] += lazy[node];
        lazy[node * 2 + 1] += lazy[node];
        lazy[node] = 0;
    }
}

void update(int node, int s, int e, int l, int r, long long x)
{
    if (r < s || e < l)
    {
        return;
    }
    if (l <= s && e <= r)
    {
        tree[node] += x * (e - s + 1);
        lazy[node] += x;
        return;
    }
    push(node, s, e);
    int mid = (s + e) / 2;
    update(node * 2, s, mid, l, r, x);
    update(node * 2 + 1, mid + 1, e, l, r, x);
    tree[node] = tree[node * 2] + tree[node * 2 + 1];
}

long long query(int node, int s, int e, int l, int r)
{
    if (r < s || e < l)
    {
        return 0;
    }
    if (l <= s && e <= r)
    {
        return tree[node];
    }
    push(node, s, e);
    int mid = (s + e) / 2;
    return query(node * 2, s, mid, l, r) + query(node * 2 + 1, mid + 1, e, l, r);
}

int main()
{
    int n, q;
    scanf("%d %d", &n, &q);
    for (int i = 1; i <= n; i++)
    {
        scanf("%d", &value[i]);
    }
    build(1, 1, n);
    for (int k = 0; k < q; k++)
    {
        int type, l, r;
        scanf("%d %d %d", &type, &l, &r);
        if (type == 1)
        {
            int x;
            scanf("%d", &x);
            update(1, 1, n, l, r, x);
        }
        else
        {
            printf("%lld\n", query(1, 1, n, l, r));
        }
    }
    return 0;
}

