#include <stdio.h>

#define LOG 15

int head[20001], nxt[40000], to[40000], depth[20001], queue[20001], seen[20001];
int up[LOG][20001];

int lca(int u, int v)
{
    if (depth[u] < depth[v])
    {
        int t = u;
        u = v;
        v = t;
    }
    for (int k = LOG - 1; k >= 0; k--)
    {
        if (depth[u] - (1 << k) >= depth[v])
        {
            u = up[k][u];
        }
    }
    if (u == v)
    {
        return u;
    }
    for (int k = LOG - 1; k >= 0; k--)
    {
        if (up[k][u] != up[k][v])
        {
            u = up[k][u];
            v = up[k][v];
        }
    }
    return up[0][u];
}

int main()
{
    int n, q, edges = 0;
    scanf("%d", &n);
    for (int i = 0; i < n - 1; i++)
    {
        int a, b;
        scanf("%d %d", &a, &b);
        to[edges] = b;
        nxt[edges] = head[a];
        head[a] = ++edges;
        to[edges] = a;
        nxt[edges] = head[b];
        head[b] = ++edges;
    }
    int qh = 0, qt = 0;
    queue[qt++] = 1;
    seen[1] = 1;
    up[0][1] = 1;
    while (qh < qt)
    {
        int u = queue[qh++];
        for (int e = head[u]; e != 0; e = nxt[e - 1])
        {
            int v = to[e - 1];
            if (!seen[v])
            {
                seen[v] = 1;
                depth[v] = depth[u] + 1;
                up[0][v] = u;
                queue[qt++] = v;
            }
        }
    }
    for (int k = 1; k < LOG; k++)
    {
        for (int v = 1; v <= n; v++)
        {
            up[k][v] = up[k - 1][up[k - 1][v]];
        }
    }
    scanf("%d", &q);
    for (int i = 0; i < q; i++)
    {
        int u, v;
        scanf("%d %d", &u, &v);
        printf("%d\n", lca(u, v));
    }
    return 0;
}

