long long dp[201][201];
long long sum[201];

int main()
{
    int n;
    scanf("%d", &n);
    for (int i = 1; i <= n; i++)
    {
        int w;
        scanf("%d", &w);
        sum[i] = sum[i - 1] + w;
    }
    for (int len = 2; len <= n; len++)
    {
        for (int i = 1; i + len - 1 <= n; i++)
        {
            int j = i + len - 1;
            long long best = -1;
            for (int k = i; k < j; k++)
            {
                long long cost = dp[i][k] + dp[k + 1][j];
                if (best < 0 || cost < best)
                {
                    best = cost;
                }
            }
            dp[i][j] = best + sum[j] - sum[i - 1];
        }
    }
    printf("%lld\n", dp[1][n]);
    return 0;
}

