#include <stdio.h>
#include <stdlib.h>

typedef struct
{
    long long x;
    long long y;
} Point;

Point p[20000], hull[40001];

int compare(const void *a, const void *b)
{
    const Point *s = a;
    const Point *t = b;
    if (s->x != t->x)
    {
        return (s->x > t->x) - (s->x < t->x);
    }
    return (s->y > t->y) - (s->y < t->y);
}

long long cross(Point o, Point a, Point b)
{
    return (a.x - o.x) * (b.y - o.y) - (a.y - o.y) * (b.x - o.x);
}

int main()
{
    int n, k = 0;
    scanf("%d", &n);
    for (int i = 0; i < n; i++)
    {
        scanf("%lld %lld", &p[i].x, &p[i].y);
    }
    qsort(p, n, sizeof(Point), compare);
    for (int i = 0; i < n; i++)
    {
        while (k >= 2 && cross(hull[k - 2], hull[k - 1], p[i]) <= 0)
        {
            k--;
        }
        hull[k++] = p[i];
    }
    for (int i = n - 2, lower = k + 1; i >= 0; i--)
    {
        while (k >= lower && cross(hull[k - 2], hull[k - 1], p[i]) <= 0)
        {
            k--;
        }
        hull[k++] = p[i];
    }
    long long area = 0;
    for (int i = 0; i < k - 1; i++)
    {
        area += hull[i].x * hull[i + 1].y - hull[i + 1].x * hull[i].y;
    }
    if (area < 0)
    {
        area = -area;
    }
    printf("%lld\n", area);
    return 0;
}

